/// The table for a CSS family name, matched case-insensitively.
pub fn table_for_family(family: &str) -> Option<&'static FontTable> {
    FONT_TABLES.iter().find(|table| table.family.eq_ignore_ascii_case(family))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The width of `Hamburgefonstiv` at 16px from a family's table, the way
    /// the text engine sums a run: advances for the covered characters plus
    /// the kern pairs between them.
    fn width(family: &str, text: &str) -> Option<f32> {
        let table = table_for_family(family)?;
        let mut units = 0.0f32;
        for ch in text.chars() {
            let code = ch as u32;
            let advance = if (0x20..=0x7E).contains(&code) {
                table.ascii[(code - 0x20) as usize]
            } else if (0xA0..=0xFF).contains(&code) {
                table.latin1[(code - 0xA0) as usize]
            } else {
                continue;
            };
            units += advance;
        }
        let mut previous: Option<char> = None;
        for ch in text.chars() {
            if let Some(first) = previous {
                let key = ((first as u32) << 16) | (ch as u32);
                if let Some((_, value)) = table.kern.iter().find(|(pair, _)| *pair == key) {
                    units += *value as f32;
                }
            }
            previous = Some(ch);
        }
        Some(units * 16.0 / table.upem)
    }

    /// Every width the challenge tracker recorded from the passing Chrome
    /// sessions, reproduced from this host's own font files. These are the
    /// values a probed family has to answer; a regeneration that drifts from
    /// any of them is wrong.
    #[test]
    fn tables_reproduce_the_reference_widths() {
        let expected: &[(&str, f32)] = &[
    ("Helvetica", 120.945f32),
    ("Helvetica Neue", 122.24f32),
    ("Arial", 120.945f32),
    ("Times", 111.695f32),
    ("Times New Roman", 111.688f32),
    ("Courier", 144.023f32),
    ("Courier New", 144.023f32),
    ("Menlo", 144.492f32),
    ("Monaco", 144.023f32),
    ("Geneva", 131.734f32),
    ("Verdana", 137.578f32),
    ("Tahoma", 120.023f32),
    ("Trebuchet MS", 121.25f32),
    ("Georgia", 124.148f32),
    ("PingFang SC", 126.512f32),
    ("Hiragino Sans GB", 137.248f32),
    ("STHeiti", 132.448f32),
    ("Songti SC", 114.4f32),
    ("Heiti SC", 132.448f32),
    ("Arial Unicode MS", 120.945f32),
    ("Comic Sans MS", 128.18f32),
    ("Impact", 113.109f32),
    ("Papyrus", 121.344f32),
    ("Copperplate", 142.256f32),
    ("Optima", 117.968f32),
    ("Futura", 122.938f32),
    ("Baskerville", 111.734f32),
    ("Didot", 124.864f32),
    ("Chalkboard", 119.266f32),
    ("Apple Symbols", 93.5391f32),
    ("Galvji", 138.4922f32),
    ("Luminari", 130.2399f32),
    ("InaiMathi", 106.7199f32),
    ("Hiragino Sans", 140.9599f32),
        ];
        for (family, reference) in expected {
            let measured = width(family, "Hamburgefonstiv")
                .unwrap_or_else(|| panic!("no table for {family}"));
            assert!(
                (measured - reference).abs() < 0.002,
                "{family}: table answers {measured}, reference {reference}"
            );
        }
    }

    /// Two families stay residual: no face of theirs on this host reproduces
    /// the reference width, so they are not pinned here.
    #[test]
    fn residual_families_are_documented() {
        for family in ["Zapfino", "Skia"] {
            assert!(
                width(family, "Hamburgefonstiv").is_some(),
                "{family} should still carry a table"
            );
        }
    }
}
